package zone.moddev.mc.ironagearchitecture.probe;

import java.util.*;
import java.util.concurrent.*;
import java.nio.file.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiMainMenu;
import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.item.ItemStack;
import net.minecraft.network.play.client.*;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraft.world.*;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.TickEvent;
import zone.moddev.mc.ironagearchitecture.*;
import zone.moddev.mc.ironagearchitecture.block.*;

/** Real ray hits and one vanilla click per edit, including prediction and a following rendered frame. */
final class ThatchInteractionProbe {
    final List<Map<String,Object>> rows=new ArrayList<>();final List<BlockPos> fixture=new ArrayList<>();
    final BlockPos origin=new BlockPos(Boolean.getBoolean("iaa.cityClient")?223:15,100,Boolean.getBoolean("iaa.cityClient")?223:15);
    int phase,ticks,operation;long started=System.nanoTime(),clicked,accepted,predicted,ready,frame;Future<?> setup;CompletableFuture<Status> status;
    BlockPos target,savedRoof,clickedOwner;int helperClick=-1;boolean remove;RayTraceResult hit;EnumActionResult result;
    static final class Status {boolean owner,settled,synced;String detail;}
    @SubscribeEvent public void tick(TickEvent.ClientTickEvent event){if(event.phase!=TickEvent.Phase.END||phase==9)return;try{advance();}catch(Throwable failure){failure.printStackTrace();finish(failure.toString());}}
    @SubscribeEvent public void frame(TickEvent.RenderTickEvent event){if(event.phase==TickEvent.Phase.END&&phase==5&&ready!=0&&frame==0)frame=System.nanoTime();}
    void advance()throws Exception {
        Minecraft mc=Minecraft.getMinecraft();ticks++;if(System.nanoTime()-started>240000000000L)throw new IllegalStateException("Interaction timeout phase="+phase);
        if(phase==0){if(!(mc.currentScreen instanceof GuiMainMenu)||ticks<50)return;mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.renderDistanceChunks=6;mc.gameSettings.limitFramerate=60;mc.gameSettings.clouds=0;String name=System.getProperty("iaa.previewName");mc.launchIntegratedServer(name,name,new WorldSettings(137,GameType.CREATIVE,false,false,WorldType.FLAT));phase=1;return;}
        if(mc.player==null)return;if(mc.currentScreen!=null)mc.displayGuiScreen(null);mc.setIngameNotInFocus();mc.player.capabilities.allowFlying=true;mc.player.capabilities.isFlying=true;mc.gameSettings.hideGUI=true;
        if(phase==1){camera(mc,origin.add(5,10,5));setup=mc.getIntegratedServer().addScheduledTask(()->{
            WorldServer w=mc.getIntegratedServer().worldServerForDimension(0);w.getGameRules().setOrCreateGameRule("doDaylightCycle","false");w.getGameRules().setOrCreateGameRule("doMobSpawning","false");w.getGameRules().setOrCreateGameRule("doFireTick","false");
            for(int x=-1;x<=1;x++)for(int z=-1;z<=4;z++)w.getChunkFromChunkCoords((origin.getX()>>4)+x,(origin.getZ()>>4)+z);
            if(Boolean.getBoolean("iaa.cityClient"))for(int x=-12;x<=12;x++)for(int z=-12;z<=12;z++)for(int y=60;y<=90;y++){BlockPos p=origin.add(x,y-origin.getY(),z);if(SmartThatchBlock.owner(w.getBlockState(p))&&(savedRoof==null||p.getY()>savedRoof.getY()||p.getY()==savedRoof.getY()&&p.distanceSq(origin)<savedRoof.distanceSq(origin)))savedRoof=p;}
            for(int row=0;row<4;row++)for(int x=0;x<10;x++){BlockPos p=origin.add(x,0,row*4);w.setBlockState(p.down(),ArchitectureBlocks.SMART_COB.getDefaultState(),3);if(x!=4){w.setBlockState(p,ArchitectureBlocks.SMART_THATCH.getDefaultState(),3);fixture.add(p);}}
            for(int x=0;x<10;x++)for(int z=0;z<9;z++){BlockPos p=origin.add(x,Math.min(x,9-x),24+z);w.setBlockState(p,ArchitectureBlocks.SMART_THATCH.getDefaultState(),3);fixture.add(p);}
            for(net.minecraft.entity.player.EntityPlayer p:w.playerEntities)if(p instanceof EntityPlayerMP){EntityPlayerMP player=(EntityPlayerMP)p;player.setGameType(GameType.CREATIVE);player.capabilities.allowFlying=true;player.capabilities.isFlying=true;player.sendPlayerAbilities();player.connection.setPlayerLocation(origin.getX()+5,origin.getY()+12.7,origin.getZ()+5,0,45);}
        });phase=2;ticks=0;return;}
        if(phase==2){if(!setup.isDone()||ticks<40)return;setup.get();if(status==null)request(mc);if(!status.isDone())return;Status s=status.get();status=null;if(!s.settled||!s.synced)return;phase=3;ticks=0;}
        if(phase==3){if(operation>=base()+2){finish("");return;}remove=operation>=4&&operation%2==0;target=operation==12?savedRoof:operation<4?origin.add(4,0,operation*4):origin.add(1,1,27);helperClick=operation-base();clickedOwner=null;if(helperClick==0){remove=true;target=origin.add(1,1,27);clickedOwner=target;}else if(helperClick==1){remove=false;clickedOwner=origin.add(2,2,24);target=clickedOwner.north();}ItemStack stack=new ItemStack(ArchitectureBlocks.SMART_THATCH,64);mc.player.inventory.currentItem=0;mc.player.inventory.setInventorySlotContents(0,stack);mc.getConnection().sendPacket(new CPacketHeldItemChange(0));mc.getConnection().sendPacket(new CPacketCreativeInventoryAction(36,stack.copy()));view(mc);mc.player.sendPlayerAbilities();mc.getConnection().sendPacket(new CPacketPlayer.PositionRotation(mc.player.posX,mc.player.posY,mc.player.posZ,mc.player.rotationYaw,mc.player.rotationPitch,false));phase=4;ticks=0;return;}
        if(phase==4||phase==5)view(mc);
        if(phase==4){if(ticks<3)return;Vec3d eye=SmartThatchBlock.eyes(mc.player),look=SmartThatchBlock.look(mc.player);hit=mc.world.rayTraceBlocks(eye,eye.add(look.scale(5)),false,false,false);if(hit==null)throw new IllegalStateException("No ray hit for "+target);if(helperClick>=0&&!SmartThatchBlock.active(mc.world.getBlockState(hit.getBlockPos())))throw new IllegalStateException("Expected underside ray hit, got "+hit.getBlockPos());if(helperClick==1&&hit.sideHit!=EnumFacing.NORTH)throw new IllegalStateException("Expected cut-edge north face, got "+hit.sideHit);if(savedRoof!=null&&operation==12)target=hit.getBlockPos();clicked=System.nanoTime();accepted=predicted=ready=frame=0;if(remove){mc.playerController.clickBlock(hit.getBlockPos(),hit.sideHit);result=EnumActionResult.SUCCESS;}else result=mc.playerController.processRightClickBlock(mc.player,mc.world,mc.player.getHeldItemMainhand(),hit.getBlockPos(),hit.sideHit,hit.hitVec,EnumHand.MAIN_HAND);if(SmartThatchBlock.owner(mc.world.getBlockState(target))!=remove)predicted=System.nanoTime();phase=5;ticks=0;return;}
        if(phase==5){if(status==null)request(mc);if(!status.isDone())return;Status s=status.get();status=null;if(s.owner!=remove&&accepted==0)accepted=System.nanoTime();if(accepted!=0&&s.settled&&s.synced&&ready==0)ready=System.nanoTime();if(ready!=0&&frame!=0||System.nanoTime()-clicked>4000000000L){boolean ok=ready!=0&&frame!=0;Map<String,Object> row=new LinkedHashMap<>();row.put("operation",operation);row.put("kind",helperClick==0?"mine underside":helperClick==1?"extend through underside edge":operation==12?"mine saved city roof":operation<4?"fill gap above cob":remove?"mine pitched section":"replace pitched section");row.put("result",result.toString());row.put("clientPredictionMs",predicted==0?null:(predicted-clicked)/1e6);row.put("acceptedMs",accepted==0?null:(accepted-clicked)/1e6);row.put("settledAndSyncedMs",ready==0?null:(ready-clicked)/1e6);row.put("frameAfterSyncMs",frame==0?null:(frame-clicked)/1e6);row.put("roofPackets",0);row.put("passed",ok);row.put("detail",s.detail);rows.add(row);System.out.println("IAA_THATCH_CLICK "+new com.google.gson.Gson().toJson(row));if(operation==3||operation==7||operation==11||operation>=12)net.minecraft.util.ScreenShotHelper.saveScreenshot(mc.mcDataDir,"thatch-click-"+operation+".png",mc.displayWidth,mc.displayHeight,mc.getFramebuffer());operation++;phase=3;ticks=0;}}
    }
    int base(){return savedRoof==null?12:13;}
    void view(Minecraft mc){if(helperClick<0&&operation>=4&&!remove&&operation<base()){double x=target.getX()+.5,z=target.getZ()+.7,y=target.getY()+1.1;mc.player.setPosition(x,y,z);mc.player.prevPosX=mc.player.lastTickPosX=x;mc.player.prevPosY=mc.player.lastTickPosY=y;mc.player.prevPosZ=mc.player.lastTickPosZ=z;MPClientProbe.aim(mc,new Vec3d(target).addVector(.5,.25,0));mc.player.prevRotationYaw=mc.player.rotationYaw;mc.player.prevRotationPitch=mc.player.rotationPitch;return;}if(helperClick<0){camera(mc,target);return;}BlockPos p=clickedOwner;double x=p.getX()+(helperClick==0?.25:.25),z=p.getZ()+(helperClick==0?.5:-2),eye=p.getY()+(helperClick==0?-1.8:-.125),y=eye-mc.player.getEyeHeight();mc.player.setPosition(x,y,z);mc.player.prevPosX=mc.player.lastTickPosX=x;mc.player.prevPosY=mc.player.lastTickPosY=y;mc.player.prevPosZ=mc.player.lastTickPosZ=z;MPClientProbe.aim(mc,new Vec3d(p).addVector(.25,-.125,helperClick==0?.5:0));mc.player.prevRotationYaw=mc.player.rotationYaw;mc.player.prevRotationPitch=mc.player.rotationPitch;}
    static void camera(Minecraft mc,BlockPos p){double x=p.getX()+.5,y=p.getY()+2.7,z=p.getZ()+.5;mc.player.setPosition(x,y,z);mc.player.prevPosX=mc.player.lastTickPosX=x;mc.player.prevPosY=mc.player.lastTickPosY=y;mc.player.prevPosZ=mc.player.lastTickPosZ=z;MPClientProbe.aim(mc,new Vec3d(p).addVector(.5,0,.5));mc.player.prevRotationYaw=mc.player.rotationYaw;mc.player.prevRotationPitch=mc.player.rotationPitch;}
    void request(Minecraft mc){CompletableFuture<Status> next=new CompletableFuture<>();status=next;mc.getIntegratedServer().addScheduledTask(()->{try{next.complete(capture(mc));}catch(Throwable failed){next.completeExceptionally(failed);}});}
    Status capture(Minecraft mc){WorldServer w=mc.getIntegratedServer().worldServerForDimension(0);Status s=new Status();s.owner=target!=null&&SmartThatchBlock.owner(w.getBlockState(target));s.settled=!SmartChunkWork.pending(w)&&!SmartCobEvents.pending(w)&&!SmartWallEvents.pending(w);s.synced=true;if(target==null){for(BlockPos p:fixture)if(!same(w,mc.world,p)){s.synced=false;break;}}else for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++)if(!same(w,mc.world,target.add(x,y,z))){s.synced=false;s.detail="state differs at "+target.add(x,y,z);}return s;}
    static boolean same(World a,World b,BlockPos p){IBlockState x=a.getBlockState(p),y=b.getBlockState(p);if(SmartThatchBlock.owner(x)!=SmartThatchBlock.owner(y))return false;if(SmartThatchBlock.active(x)!=SmartThatchBlock.active(y))return false;if(SmartThatchBlock.active(x)){BlockPos u=SmartThatchBlock.parent(a,p),v=SmartThatchBlock.parent(b,p);return u!=null&&v!=null&&ThatchShape.at(a,u,a.getBlockState(u))==ThatchShape.at(b,v,b.getBlockState(v));}return !SmartThatchBlock.owner(x)||ThatchShape.at(a,p,x)==ThatchShape.at(b,p,y);}
    void finish(String error){if(phase==9)return;phase=9;Minecraft mc=Minecraft.getMinecraft();Map<String,Object> result=new LinkedHashMap<>();result.put("passed",error.isEmpty()&&rows.size()==base()+2&&rows.stream().allMatch(r->Boolean.TRUE.equals(r.get("passed"))));result.put("error",error);result.put("runtimeSha256",System.getProperty("iaa.runtimeSha256"));result.put("city",Boolean.getBoolean("iaa.cityClient"));result.put("finiteShapes",ThatchShape.COUNT*4);result.put("operations",rows);try{Files.write(mc.mcDataDir.toPath().resolve("thatch-interaction.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(result).getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception failure){throw new IllegalStateException(failure);}System.out.println("IAA_CLIENT_PROBE_"+(Boolean.TRUE.equals(result.get("passed"))?"PASS":"FAIL")+" simpleThatchInteraction");mc.shutdown();}
}
